with TopContributors as (
    select 
        u.Id,
        u.DisplayName,
        count(distinct b.Id) total_badges,
        sum(case when b.Class = 1 then 1 else 0 end) gold_badges,
        sum(case when b.Class = 2 then 1 else 0 end) silver_badges,
        sum(case when b.Class = 3 then 1 else 0 end) bronze_badges,
        row_number() over (order by count(distinct b.Id) desc, u.Reputation desc) rn
    from Users u
    left join Badges b
        on b.UserId = u.Id
    group by u.Id, u.DisplayName
    having count(distinct b.Id) > 5
